Skills 0, 1 and 2 look additive mod 16 and skill 3 looks xor, so I read off per-row and per-column offsets by voting over the predicted grid, which is rule inference and touches no weights.
```python
import numpy as np
P=np.load("P.npy")
ops={"add":(lambda x,y:(x+y)%16, lambda t,y:(t-y)%16),"xor":(lambda x,y:x^y, lambda t,y:t^y)}
res={}
for s in range(4):
    M=P[s]
    for name,(op,inv) in ops.items():
        best=None
        for a0 in range(32):
            g=M[a0].copy();f=np.zeros(32,int)
            for it in range(6):
                for a in range(32): f[a]=np.bincount(inv(M[a],g),minlength=16).argmax()
                for b in range(32): g[b]=np.bincount(inv(M[:,b],f),minlength=16).argmax()
            acc=(op(f[:,None],g[None,:])==M).mean()
            if best is None or acc>best[0]: best=(acc,f.copy(),g.copy())
        res[(s,name)]=best
        print("skill",s,name,"agreement %.3f"%best[0])
        print("  f",best[1].tolist());print("  g",best[2].tolist())
import pickle;pickle.dump(res,open("rules.pkl","wb"))
