Residuals pile on a few values, so plain Z16 is probably wrong; I group rows and columns that predict the same classes and read a majority table between groups, which shows the rule without assuming a group.
```python
import numpy as np,pickle
P=np.load("P.npy")
np.set_printoptions(linewidth=250)
def cluster(M,th):
    n=M.shape[0];E=np.array([[ (M[i]==M[j]).mean() for j in range(n)] for i in range(n)])
    lab=-np.ones(n,int);k=0
    for i in range(n):
        if lab[i]<0:
            st=[i];lab[i]=k
            while st:
                u=st.pop()
                for v in range(n):
                    if lab[v]<0 and E[u,v]>=th: lab[v]=k;st.append(v)
            k+=1
    return lab,k,E
out={}
for s in range(4):
    M=P[s]
    for th in [0.5]:
        ra,ka,Ea=cluster(M,th);rb,kb,Eb=cluster(M.T,th)
        offd=Ea[np.triu_indices(32,1)]
        print("skill",s,"th",th,"row groups",ka,"col groups",kb,"row pair eq hist(0-1 by .1)",np.histogram(offd,bins=10,range=(0,1))[0].tolist())
        print(" ra",ra.tolist());print(" rb",rb.tolist())
    T=-np.ones((ka,kb),int);C=np.zeros((ka,kb))
    for i in range(ka):
        for j in range(kb):
            v=M[np.ix_(ra==i,rb==j)].ravel()
            if len(v):
                c=np.bincount(v,minlength=16);T[i,j]=c.argmax();C[i,j]=c.max()/len(v)
    out[s]=(ra,rb,T,C)
    print(" table purity %.3f"%((C*np.outer(np.bincount(ra),np.bincount(rb))).sum()/1024))
    if ka<=20 and kb<=20: print(T)
pickle.dump(out,open("tab.pkl","wb"))
